-- Central application-service compatibility contracts; transport adapters do not execute providers.
-- Source reviews: Engineering Control v35, deployment API v34, provision v52 and engineering test API v4.
-- New mutations remain disabled/unverified. Existing verification, exposure and evidence are preserved.
-- engineering.rollback.verify is corrected from read to mutation/engineering:execute because its backend persists completion/audit.
BEGIN;
CREATE FUNCTION public.sandy_api_legacy_operation_scope(p_actor_id uuid,p_change_id uuid,p_operation text)
RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER
SET search_path=pg_catalog,pg_temp AS $scope$
 SELECT p_operation = ANY(ARRAY['engineering.models.canary','deployment.management.deploy_smoke','deployment.functions.register','google_cloud.iam.runtime_create','google_cloud.iam.runtime_prepare','google_cloud.iam.grant_deployment','google_cloud.mcp.build_bootstrap','google_cloud.mcp.builder_project_grant','google_cloud.mcp.registry_writer_grant','google_cloud.mcp.release_temp_iam','google_cloud.mcp.public_ingress','google_cloud.mcp.cloud_run_deploy','google_cloud.mcp.container_build','video.ssh.iam_grant','video.osconfig.enable','video.osconfig.vm_prepare']::text[]) AND
   EXISTS(SELECT 1 FROM public.sandy_controller_admins WHERE auth_user_id=p_actor_id AND enabled=true AND role='owner') AND
   EXISTS(SELECT 1 FROM public.sandy_engineering_changes WHERE id=p_change_id
     AND status IN ('approved','implementing') AND jsonb_typeof(scope)='array'
     AND scope @> jsonb_build_array(p_operation));
$scope$;
REVOKE ALL ON FUNCTION public.sandy_api_legacy_operation_scope(uuid,uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.sandy_api_legacy_operation_scope(uuid,uuid,text) TO service_role;

CREATE FUNCTION public.sandy_api_legacy_cloud_targets(p_actor_id uuid)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER
SET search_path=pg_catalog,pg_temp AS $targets$
DECLARE targets jsonb;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.sandy_controller_admins WHERE auth_user_id=p_actor_id AND enabled=true AND role='owner') THEN
   RETURN jsonb_build_object('ok',false,'error','owner_required','http_status',403);
 END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(target) ORDER BY target.name),'[]'::jsonb) INTO targets
 FROM (SELECT name,project_id,zone,protected,purpose FROM public.sandy_cloud_targets ORDER BY name LIMIT 200) target;
 RETURN jsonb_build_object('ok',true,'contract_version','1.0.0','targets',targets,'result_limit',200,'possibly_truncated',jsonb_array_length(targets)=200);
END $targets$;
REVOKE ALL ON FUNCTION public.sandy_api_legacy_cloud_targets(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.sandy_api_legacy_cloud_targets(uuid) TO service_role;

CREATE FUNCTION public.sandy_api_legacy_deployment_status(p_actor_id uuid,p_job_id uuid)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER
SET search_path=pg_catalog,pg_temp AS $status$
DECLARE job jsonb; external_evidence jsonb;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.sandy_controller_admins WHERE auth_user_id=p_actor_id AND enabled=true AND role='owner') THEN
   RETURN jsonb_build_object('ok',false,'error','owner_required','http_status',403);
 END IF;
 SELECT to_jsonb(selected) INTO job FROM
   (SELECT id,status,provider,operation,target,created_at,finished_at,result,error
    FROM public.sandy_deployment_jobs WHERE id=p_job_id) selected;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'error','job_not_found','http_status',404); END IF;
 IF job->>'provider'='supabase' AND job->>'operation'='deploy_function' THEN
   SELECT to_jsonb(selected) INTO external_evidence FROM
     (SELECT event_type,occurred_at,details FROM public.sandy_deployment_events
      WHERE job_id=p_job_id AND event_type='external_deployment_observed'
      ORDER BY occurred_at DESC,id DESC LIMIT 1) selected;
   IF FOUND THEN
     job := job || jsonb_build_object('external_deployment_evidence',external_evidence,
       'worker_execution_status',CASE WHEN job->>'status' IN ('pending_approval','approved') THEN 'not_executed'
         ELSE 'recorded_' || coalesce(job->>'status','unknown') END,
       'requires_reconciliation',true);
   END IF;
 END IF;
 RETURN jsonb_build_object('ok',true,'contract_version','1.0.0','job',job);
END $status$;
REVOKE ALL ON FUNCTION public.sandy_api_legacy_deployment_status(uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.sandy_api_legacy_deployment_status(uuid,uuid) TO service_role;

